<div class="container"><!-- CABECERA CON LOGO DEL IES --><header class="cabecera"><img src="{{context_path}}/content/resources/logo-ies.png" alt="Logo IES Virgen de la Luz" class="logo" />
<div class="titulos">
<h1>LOS ELEMENTOS QUÍMICOS Y SUS SÍMBOLOS</h1>
<p class="subtitulo">Departamento de Física y Química</p>
</div>
</header>
<div class="score" id="score">Aciertos: 0/0</div>
<div class="question-box">
<div class="question-text" id="question"></div>
<input type="text" id="answer" placeholder="ESCRIBE TU RESPUESTA" aria-label="Respuesta" onkeypress="handleKeyPress(event)" />
<div class="feedback" id="feedback"></div>
<button onclick="checkAnswer()">COMPROBAR RESPUESTA</button></div>
<div id="final" class="final-score"></div>
</div>
