<p>© IES Virgen de la Luz · Uso educativo</p>
</footer>
<p>
<script>
        const elements = [
            {symbol: 'H', names: ['hidrogeno', 'hidrógeno']},
            {symbol: 'Li', names: ['litio']},
            {symbol: 'Na', names: ['sodio']},
            {symbol: 'K', names: ['potasio']},
            {symbol: 'Rb', names: ['rubidio']},
            {symbol: 'Cs', names: ['cesio']},
            {symbol: 'Fr', names: ['francio']},
            {symbol: 'Be', names: ['berilio']},
            {symbol: 'Mg', names: ['magnesio']},
            {symbol: 'Ca', names: ['calcio']},
            {symbol: 'Sr', names: ['estroncio']},
            {symbol: 'Ba', names: ['bario']},
            {symbol: 'Ra', names: ['radio']},
            {symbol: 'B', names: ['boro']},
            {symbol: 'Al', names: ['aluminio']},
            {symbol: 'Ga', names: ['galio']},
            {symbol: 'In', names: ['indio']},
            {symbol: 'Tl', names: ['talio']},
            {symbol: 'C', names: ['carbono']},
            {symbol: 'Si', names: ['silicio']},
            {symbol: 'Ge', names: ['germanio']},
            {symbol: 'Sn', names: ['estaño']},
            {symbol: 'Pb', names: ['plomo']},
            {symbol: 'N', names: ['nitrogeno', 'nitrógeno']},
            {symbol: 'P', names: ['fosforo', 'fósforo']},
            {symbol: 'As', names: ['arsenico', 'arsénico']},
            {symbol: 'Sb', names: ['antimonio']},
            {symbol: 'Bi', names: ['bismuto']},
            {symbol: 'O', names: ['oxigeno', 'oxígeno']},
            {symbol: 'S', names: ['azufre']},
            {symbol: 'Se', names: ['selenio']},
            {symbol: 'Te', names: ['telurio', 'teluro']},
            {symbol: 'F', names: ['fluor', 'flúor']},
            {symbol: 'Cl', names: ['cloro']},
            {symbol: 'Br', names: ['bromo']},
            {symbol: 'I', names: ['yodo']},
            {symbol: 'Ne', names: ['neon', 'neón']},
            {symbol: 'Ar', names: ['argon', 'argón']},
            {symbol: 'Kr', names: ['kripton', 'kriptón']},
            {symbol: 'Xe', names: ['xenon', 'xenón']},
            {symbol: 'Rn', names: ['radon', 'radón']},
            {symbol: 'Cr', names: ['cromo']},
            {symbol: 'Mn', names: ['manganeso']},
            {symbol: 'Fe', names: ['hierro']},
            {symbol: 'Co', names: ['cobalto']},
            {symbol: 'Ni', names: ['niquel', 'níquel']},
            {symbol: 'Cu', names: ['cobre']},
            {symbol: 'Zn', names: ['zinc', 'cinc']},
            {symbol: 'Pd', names: ['paladio']},
            {symbol: 'Ag', names: ['plata']},
            {symbol: 'Cd', names: ['cadmio']},
            {symbol: 'Pt', names: ['platino']},
            {symbol: 'Au', names: ['oro']},
            {symbol: 'Hg', names: ['mercurio']}
        ];

        let selectedElements = [];
        let currentQuestionIndex = 0;
        let currentElement;
        let questionType;
        let correctAnswers = 0;
        let baseDelay = 1500;

        function handleKeyPress(event) {
            if(event.key === 'Enter') checkAnswer();
        }

        function normalizeString(str) {
            return str.toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "");
        }

        function shuffle(array) {
            for (let i = array.length - 1; i > 0; i--) {
                const j = Math.floor(Math.random() * (i + 1));
                [array[i], array[j]] = [array[j], array[i]];
            }
            return array;
        }

        function startGame() {
            selectedElements = shuffle([...elements]);
            currentQuestionIndex = 0;
            correctAnswers = 0;
            baseDelay = 1500;
            document.getElementById('score').textContent = 'Aciertos: 0/0';
            document.querySelector('.question-box').style.display = 'block';
            document.getElementById('final').innerHTML = '';
            nextQuestion();
        }

        function nextQuestion() {
            if(currentQuestionIndex >= elements.length) { showFinalScore(); return; }
            currentElement = selectedElements[currentQuestionIndex];
            questionType = Math.random() < 0.5 ? 'symbol' : 'name';
            document.getElementById('question').textContent = questionType === 'symbol' 
                ? `¿Qué elemento tiene el símbolo ${currentElement.symbol}?`
                : `¿Cuál es el símbolo de ${currentElement.names[0]}?`;
            document.getElementById('answer').value = '';
            document.getElementById('feedback').textContent = '';
            document.getElementById('answer').focus();
        }

        function checkAnswer() {
            const userAnswer = document.getElementById('answer').value.trim();
            let isCorrect = false, correctAnswer;
            if(questionType === 'symbol') {
                const normalizedUser = normalizeString(userAnswer);
                isCorrect = currentElement.names.some(name => normalizedUser === normalizeString(name));
                correctAnswer = currentElement.names[0];
            } else {
                isCorrect = userAnswer === currentElement.symbol;
                correctAnswer = currentElement.symbol;
            }
            if(isCorrect) {
                correctAnswers++;
                document.getElementById('feedback').textContent = '¡Correcto!';
                document.getElementById('feedback').style.color = 'var(--success)';
                baseDelay = Math.max(500, baseDelay - 100);
            } else {
                document.getElementById('feedback').textContent = `Incorrecto. La respuesta correcta es: ${correctAnswer}`;
                document.getElementById('feedback').style.color = 'var(--danger)';
                baseDelay = 1500;
            }
            document.getElementById('score').textContent = `Aciertos: ${correctAnswers}/${currentQuestionIndex + 1}`;
            currentQuestionIndex++;
            if(currentQuestionIndex < elements.length) {
                setTimeout(nextQuestion, isCorrect ? baseDelay : 1500);
            } else {
                showFinalScore();
            }
        }

        function showFinalScore() {
            const totalQuestions = elements.length;
            const percentage = (correctAnswers / totalQuestions) * 100;
            let message;
            if(percentage >= 90) message = '¡Excelente! Dominas los elementos químicos 🎉';
            else if(percentage >= 70) message = '¡Buen trabajo! Sigue practicando 💪';
            else if(percentage >= 50) message = '¡Vas mejorando! Repasa los que fallaste 📚';
            else message = '¡Sigue intentándolo! La práctica hace al maestro 💡';
            document.getElementById('final').innerHTML = `
                <h2>Resultado final: ${correctAnswers}/${totalQuestions}</h2>
                <p>${percentage.toFixed(1)}% de aciertos</p>
                <p>${message}</p>
                <button onclick="startGame()">Volver a intentar</button>
            `;
            document.querySelector('.question-box').style.display = 'none';
        }

        startGame();
    </script>
</p>","textFeedbackInput":"Mostrar retroalimentación","textFeedbackTextarea":""}
